/* 맵 퍼스트 UI — MapViewSheet / UserInfoSheet 와 맞춘 다크 글래스 톤 */
.auth-gate {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(0.65rem, env(safe-area-inset-top, 0px))
    max(0.65rem, env(safe-area-inset-right, 0px))
    max(0.65rem, env(safe-area-inset-bottom, 0px))
    max(0.65rem, env(safe-area-inset-left, 0px));
  background: rgba(2, 6, 23, 0.42);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.auth-gate__card {
  width: min(16.5rem, 92vw);
  max-height: 100%;
  overflow: auto;
  border-radius: 14px;
  background: #FFFFFF;
  border: 1px solid #CBD5E1;
  color: #1F2937;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.38);
  padding: 0.65rem 0.75rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  color-scheme: light;
  animation: auth-gate-card-in 0.2s ease-out;
}

@keyframes auth-gate-card-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.auth-gate__topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.45rem;
}

.auth-gate__brand {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  flex: 1;
  font-weight: 700;
  letter-spacing: 0.08em;
  font-size: 0.68rem;
  color: rgba(31, 41, 55, 0.92);
}

.auth-gate__brand-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: #2563EB;
  box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.25);
  flex-shrink: 0;
}

.auth-gate__close {
  flex-shrink: 0;
  box-sizing: border-box;
  width: 1.85rem;
  height: 1.85rem;
  margin: 0;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  appearance: none;
  border: 1px solid #CBD5E1;
  border-radius: 50%;
  background: #F1F5F9;
  color: #475569;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease;
}

.auth-gate__close:hover:not(:disabled) {
  background: #EFF6FF;
}

.auth-gate__close:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 2px;
}

.auth-gate__close:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.auth-gate__title {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: rgba(31, 41, 55, 0.88);
}

.auth-gate__body {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

/* 카드 내 공통 버튼 — UserInfoSheet 버튼과 유사 */
.auth-gate__card .btn {
  appearance: none;
  font: inherit;
  font-weight: 600;
  font-size: 0.74rem;
  padding: 0.42rem 0.6rem;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #475569;
  cursor: pointer;
  transition: background 0.15s ease;
}

.auth-gate__card .btn:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #2563EB;
}

.auth-gate__card .btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.auth-gate__card .auth-actions {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  gap: 0.35rem;
}

.auth-gate__card .auth-actions--gate .btn {
  flex: none;
  width: 100%;
  text-align: center;
  justify-content: center;
}

/* 게스트: 중립 유지(secondary) */
.auth-gate__card .btn.secondary {
  background: #FFFFFF;
  border-color: #CBD5E1;
  color: #475569;
}

.auth-gate__card .btn.secondary:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #2563EB;
}

/* 기본 primary — 닉네임 제출 등 */
.auth-gate__card .btn.primary {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

.auth-gate__card .btn.primary:hover:not(:disabled) {
  background: #1D4ED8;
